import os
import time

from jinja2 import FileSystemLoader, Template, Environment
from taf.ul.trs_e2e_fw.lib.oam.admin.delta_parser import DeltaParser
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.admin.utils import _generate_scf
from taf.ul.trs_e2e_fw.lib.oam.admin.reset import Reset
from taf.ul.trs_e2e_fw.lib.oam.admin.cell_operations import CellOperations
from taf.ul.trs_e2e_fw.lib.oam.admin.admin_factory import AdminBaseClass

from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler
from taf.ul.trs_e2e_fw.lib.utils.verification.auto_correct_delta_commissioning.auto_correct_delta import \
    AutoCorrectionTool


logger = BackgroundLogger.Instance()


class Commissioning(AdminBaseClass):
    """
    Commissioning
    """

    def __init__(self):
        super(Commissioning, self).__init__()
        self.cell_operations = CellOperations()

    @check_rat
    def perform_commissioning(self, **kwargs):
        """ This keyword commissions bts with the scf file passed via pybot, and checks for BTS
            status
            :param skip_parameter_relation_errors: Skip parameter relation errors
            :param timeout: Time to wait for positive procedure result
            :param wait_for_onair_status: Time to wait, before checking for Cell status
            :param alias: Name of execution context
        """
        scf_file = kwargs.get("scf_file", get_config_variable(['scfc_name']))
        skip_parameter_relation_errors = kwargs.get("skip_parameter_relation_errors", True)
        verify_bts_status = kwargs.get("verify_bts_status", True)
        timeout = kwargs.get("timeout", 300)
        wait_for_onair_status = kwargs.get("wait_for_onair_status", 900)
        alias = kwargs.get("alias", "default")
        bts_id, scf_dir = self._get_btsid_and_scf_dir(alias)
        scf_file = os.path.join(scf_dir, scf_file)
        logger.debug('scf_file', scf_file)
        logger.debug("Beginning commissioning operation...")
        resp_per_comm = self.factory.admin.perform_commissioning(
            bts_id, scf_file, skip_parameter_relation_errors=skip_parameter_relation_errors, timeout=timeout,
            connection=alias)
        logger.debug("commissioning output {}".format(resp_per_comm))
        logger.debug("commissioning performed")
        # Reset().verify_bts_reset_internal(**kwargs)
        if verify_bts_status is True:
            logger.debug("verifying bts status...")
            self.cell_operations.verify_bts_status(wait_for=wait_for_onair_status, alias=alias)
        logger.debug("generating scf....")
        _generate_scf(alias)
        self._update_rat_env(alias)

    def _get_btsid_and_scf_dir(self, alias):
        chained = global_vars.alias_chained_dict[alias]
        dut = global_vars.alias_dut_dict[alias]
        if chained:
            bts_id = get_config_variable([dut, 'bts_id']) or get_config_variable(['bts_id'])
            scf_dir = get_config_variable(['chained_bts_scf_dir']).format(chained=bts_id)
        else:
            bts_id = get_config_variable(['bts_id'])
            scf_dir = get_config_variable(['scfc_path'])
        logger.debug("btsid :: {0}\tscf_dir :: {1}".format(bts_id, scf_dir))
        return bts_id, scf_dir

    @check_rat
    def perform_recommissioning(self, **kwargs):
        """ This function recommissions(delta or parameter) BTS.
            :param kwargs: type: delta/param
            :param kwargs: delta_file: if type is delta. Delta file name should be passed
            :param kwargs: skip_parameter_relation_errors. Skips parameter relation errors if True
            :param kwargs: rat: if type is param. accepted values are lte/wcdma/gsm.
                The RAT which the param belongs to. If it is RAT independent, pass lte
            :param kwargs: param_path: if type is param. The Parameter Path
                Example: IPIF-1:ipMtu
            :param kwargs:should_activate :True by default.
            :param kwargs: timeout: Time to wait for positive procedure result
            :param kwargs: alias: Name of execution context
        """

        if kwargs['type'] == 'delta':
            alias = kwargs.get("alias", "default")
            retry = 3
            error_flag = True
            while retry != 0 and error_flag:
                try:
                    self._perform_delta_recomissioning(kwargs)
                    logger.debug("Checking the stateInfo after successful Delta recommissioning")
                    self._check_bts_state_info(alias)
                    error_flag = False
                except Exception as e:
                    error_flag = self._check_for_RNW_error(e, alias=alias)
                retry -= 1
            _generate_scf(kwargs.get('alias', 'default'), kwargs.get('timeout', 120))
        elif kwargs['type'] == 'param':
            self._perform_parameter_recommissioning(kwargs)
            ncf = kwargs.get('ncf', False)
            if ncf is False:
                _generate_scf(kwargs.get('alias', 'default'), kwargs.get('timeout', 120))
        elif kwargs['type'] == 'ncf':
            self._perform_ncf_commissioning(**kwargs)

    def delta_vars_substitution(self, delta_file):
        """
        Delta vars substitution
        """
        xml_content = ''
        loader = FileSystemLoader(os.path.dirname(delta_file))
        env = Environment(loader=loader)
        template = env.get_template(os.path.basename(delta_file))
        xml_content = template.render(self.config)
        delta_file_name = os.path.basename(delta_file)
        rendered_delta = 'execution_logs/{}'.format(delta_file_name)
        if not os.path.exists(os.path.dirname(rendered_delta)):
            os.makedirs(os.path.dirname(rendered_delta))
        with open(rendered_delta, 'w') as f_file:
            f_file.write(xml_content)
        return rendered_delta

    def _perform_parameter_recommissioning(self, kwargs):
        distname, param_name = kwargs['param_path'].split(':')
        if not distname.startswith('MRBTS-'):  # If not already a full distname
            distname = self.distnames.get_full_distname_from_scf(
                distname, format_distname=False, alias=kwargs.get("alias", "default"))
            # distname = self.distnames.format_to_infomodel_compatible_distname(distname)
        logger.debug("perform parameter recommissioning....")
        retry = 3
        error_flag = True
        while retry != 0 and error_flag:
            try:
                self.factory.admin.perform_parameter_recommissioning(
                    distname, param_name, kwargs['operation'], kwargs['value'],
                    skip_parameter_relation_errors=kwargs.get('skip_parameter_relation_errors', True),
                    timeout=kwargs.get('timeout', 120), connection=kwargs.get("alias", "default"))
                logger.debug("Checking the stateInfo after successful recommissioning")
                self._check_bts_state_info(alias=kwargs.get("alias", "default"))
                error_flag = False
            except Exception as e:
                error_flag = self._check_for_RNW_error(e, alias=kwargs.get("alias", "default"))
            retry -= 1

    def add_rat(self, **kwargs):
        """
        Add rat
        """
        rat = kwargs.get('rat')
        base_scf = kwargs.get('base_scf')
        rat_scf = kwargs.get('rat_scf')
        # output_scf = kwargs.get('output_scf', None)
        timeout = kwargs.get('timeout', 60)
        alias = kwargs.get('alias', 'default')
        verify_bts_status = kwargs.get("verify_bts_status", True)
        wait_for_onair_status = kwargs.get("wait_for_onair_status", 900)
        skip_parameter_relation_errors = kwargs.get('skip_parameter_relation_errors', True)
        bts_id = get_config_variable(['bts_id'])
        plan_scf_file = os.path.join(get_config_variable(['scfc_path']), base_scf)
        rat_scf_file = os.path.join(get_config_variable(['scfc_path']), rat_scf)
        output_scf_file = 'execution_logs/{}_merged_output_scf'.format(bts_id)
        self.factory.admin.add_rat(rat_technology=rat, plan_scf_file=plan_scf_file,
                                   rat_scf_file=rat_scf_file, output_scf=output_scf_file,
                                   timeout=timeout, connection=alias)
        logger.debug("create merged output scf")
        logger.debug("commissioning enB with merged scf")
        self.factory.admin.perform_commissioning(
            bts_id, output_scf_file,
            skip_parameter_relation_errors=skip_parameter_relation_errors,
            timeout=300, connection=alias)
        logger.debug("enB commissioned with merged scf")
        if verify_bts_status is True:
            logger.debug("verifying bts status...")
            self.cell_operations.verify_bts_status(wait_for=wait_for_onair_status, alias=alias)
        logger.debug("generating scf....")
        _generate_scf(alias)

    def _perform_ncf_commissioning(self, **kwargs):
        scf_file = kwargs["scf_file"]
        verify_bts_status = kwargs.get("verify_bts_status", False)
        wait_for_onair_status = kwargs.get("wait_for_onair_status", 900)
        timeout = kwargs.get("timeout", 300)
        alias = kwargs.get("alias", "default")

        bts_id, scf_dir = self._get_btsid_and_scf_dir(alias)
        scf_file = os.path.join(scf_dir, scf_file)
        # self.factory.admin.active_ncf(scf_file=scf_file, timeout=timeout, connection=alias)
        self.factory.admin.perform_ncf_commissioning(ncf_filepath=scf_file, timeout=timeout, connection=alias)
        if verify_bts_status is True:
            logger.debug("verifying bts status...")
            self.cell_operations.verify_bts_status(wait_for=wait_for_onair_status, alias=alias)

    def _check_for_RNW_error(self, caught_error, alias):
        """This is a recovery method created to capture RNW and Cpan busy error caught
        during recommissioning"""
        error_flag = False
        if "CPlane is busy" in caught_error.__str__():
            error_flag = True
            logger.debug("Checking the stateInfo")
            self._check_bts_state_info(alias)
            logger.debug("Looks like cplane is busy. Entering 2mins wait mode")
            time.sleep(120)
            self._check_bts_state_info(alias)
        elif "ongoing RNW Plan File activation" in caught_error.__str__():
            error_flag = True
            logger.debug("RNW error found. Entering wait mode for 60sec")
            time.sleep(60)
            self._check_bts_state_info(alias)
        else:
            raise
        return error_flag

    def _check_bts_state_info(self, alias):
        resp = self.factory.admin.get_bts_info(connection=alias)
        if resp['gnsse']:
            logger.debug("stateInfo {}".format(resp['gnsse'][0]['stateInfo']))

    def _update_rat_env(self, alias):
        cell_status_dict = {}
        try:
            all_cells_data = self.factory.admin.get_managed_objects(class_name='CELL_M',
                                                                    timeout=100,
                                                                    connection=alias)
            for cell_data in all_cells_data:
                cell_rat = cell_data['parameters']['rat'].lower()
                cell_status = cell_data['parameters']['stateInfo']['proceduralState']
                if cell_rat == "nr":
                    cell_rat = "5g"
                cell_status_dict[cell_rat] = cell_status.lower()
        except Exception as err:
            logger.debug('ADMIN API exception: {}'.format(err))
        interpreted_rat_set = [k for k, v in cell_status_dict.items() if v.lower() in cell_status_dict]
        if interpreted_rat_set:
            ConfigHandler.config['rat_env'] = interpreted_rat_set
            logger.debug("updates rat_env is: ".format("".join(ConfigHandler.config['rat_env'])))

    def _perform_delta_recomissioning(self, kwargs):
        delta_file = kwargs['delta_file']
        alias = kwargs.get("alias", "default")
        timeout = kwargs.get('timeout', 120)
        activate_delta_plan = kwargs.get("should_activate", True)
        skip_parameter_relation_errors = kwargs.get('skip_parameter_relation_errors', True)
        delta_file = self.get_delta_file_full_path(delta_file=delta_file, alias=alias)
        delta_file = self.delta_vars_substitution(delta_file)
        parser_obj = DeltaParser(delta_file)
        jsonfile = parser_obj.convert_delta_xml_to_json()
        try:
            logger.debug("############### VALIDATING DELTA FILE {} ###################### ".format(jsonfile))
            self.factory.admin.perform_delta_recommissioning(
                jsonfile, skip_parameter_relation_errors=skip_parameter_relation_errors, should_activate=False,
                timeout=timeout, connection=alias)
        except Exception as e:
            if skip_parameter_relation_errors:
                logger.debug("############# RUNNING AUTOCORRECTION LOGIC #########################")
                auto_tool = AutoCorrectionTool()
                jsonfile = auto_tool.compare_delta_against_nidd(delta_file=jsonfile)
                logger.debug("############# AUTOCORRECTION COMPLETE #########################")
        finally:
            logger.debug("############### ACTIVATING DELTA FILE {} ###################### ".format(jsonfile))
            if activate_delta_plan:
                self.factory.admin.perform_delta_recommissioning(
                    jsonfile, skip_parameter_relation_errors=skip_parameter_relation_errors,
                    should_activate=activate_delta_plan, timeout=timeout, connection=alias)
